import{_ as a,o as t,c as i,a2 as e}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"常见问题","description":"","frontmatter":{"title":"常见问题"},"headers":[],"relativePath":"app-center/wordpress/faq.md","filePath":"app-center/wordpress/faq.md","lastUpdated":1794381603000}'),p={name:"app-center/wordpress/faq.md"};function n(l,s,d,h,o,r){return t(),i("div",null,[...s[0]||(s[0]=[e('<table tabindex="0"><thead><tr><th>问题</th><th>解决方案</th></tr></thead><tbody><tr><td>Let&#39;s Encrypt 证书申请失败</td><td>检查域名是否已解析到服务器 IP，确认 80 端口可公网访问</td></tr><tr><td>域名无法访问 WordPress® 站点</td><td>参考下方“本机 DNS 缓存说明”</td></tr></tbody></table><h3 id="本机-dns-缓存说明" tabindex="-1">本机 DNS 缓存说明 <a class="header-anchor" href="#本机-dns-缓存说明" aria-label="Permalink to &quot;本机 DNS 缓存说明&quot;">​</a></h3><blockquote><p><strong>注意</strong></p><p>如果您配置的域名之前指向过其他服务器，本地电脑可能存在旧的 DNS 缓存，导致访问不到 WordPress® 站点。</p></blockquote><p><strong>方法一：等待自动刷新</strong></p><p>DNS 缓存通常会在几分钟到几小时内自动更新。</p><p><strong>方法二：手动清除 DNS 缓存</strong></p><p>根据您的操作系统选择对应命令。</p><p>Windows：</p><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ipconfig /flushdns</span></span></code></pre></div><p>macOS：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dscacheutil</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -flushcache</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> killall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -HUP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mDNSResponder</span></span></code></pre></div><p>Linux：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd-resolve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --flush-caches</span></span></code></pre></div><p><strong>方法三：验证域名解析是否生效</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nslookup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 您的域名</span></span></code></pre></div><p>确认返回的 IP 地址是否为您的服务器 IP。如果 IP 地址正确但仍无法访问，请检查防火墙设置和 80/443 端口是否开放。</p>',16)])])}const g=a(p,[["render",n]]);export{k as __pageData,g as default};
